  if (Array.isArray(json)) {
    return {
      "@context": [ctxUrl, localCtx],
      ...(documentUrl ? { "@id": documentUrl } : {}),
      "@graph": json,
    };
  }
  return {
    "@context": [ctxUrl, localCtx],
    has_container: ownSpaceUrl,
    ...json,
  };
};
