import { NextResponse, NextRequest } from "next/server";
import { createClient } from "~/utils/supabase/server";
import { asPostgrestFailure } from "@repo/database/lib/contextFunctions";
import {
  defaultOptionsHandler,
  createApiResponse,
} from "~/utils/supabase/apiUtils";
import { asJsonLD, conceptName } from "~/utils/conversion/jsonld";
import { Tables } from "@repo/database/dbTypes";
import type { ColumnRow } from "@repo/database/inputTypes";
import { convert, MIMETYPES, type DocType } from "~/utils/conversion/convert";
import {
  findNode,
  loadConceptAddresses,
  nodePathFromSegments,
} from "~/utils/conversion/nodeLookup";
import { spaceDataUrl } from "~/utils/conversion/nodeAddress";

type Concept = ColumnRow<"Concept">;
type PlatformAccount = Tables<"PlatformAccount">;

export type SegmentDataType = { params: Promise<Record<string, string>> };

export const GET = async (
  request: NextRequest,
  segmentData: SegmentDataType,
): Promise<NextResponse> => {
  const {
    platform: platformSegment,
    space_key,
    local_id,
  } = await segmentData.params;
  let targetFormat: DocType = (request.nextUrl.searchParams.get("format") ??
    "html") as DocType;
  if (MIMETYPES[targetFormat] === undefined) {
    targetFormat = "html";
  }
  const targetMimetype = MIMETYPES[targetFormat];
  const includeData =
    targetFormat === "html" &&
    request.nextUrl.searchParams.get("data") !== "false";
  const nodePath = nodePathFromSegments({
    platform: platformSegment,
    spaceKey: space_key,
    localId: local_id,
  });
  if ("failure" in nodePath)
    return createApiResponse(request, nodePath.failure);
  const supabase = await createClient();
  const found = await findNode({ supabase, nodePath });
  if ("failure" in found) return createApiResponse(request, found.failure);
  const { space, concept, contents } = found;
  const platform = space.platform;
  const origin = request.nextUrl.origin;
  const ownSpaceUrl = spaceDataUrl({ origin, ...nodePath });
  const fullContents = contents.find((c) => c.variant === "full");
  const title = contents.find((c) => c.variant === "direct");

  if (!fullContents) {
    return createApiResponse(
      request,
      asPostgrestFailure("Resource content not found", "404", 404),
    );
  }

  const source: DocType | undefined =
    platform === "Obsidian"
      ? "obsidian"
      : platform === "Roam"
        ? "roam"
        : undefined;
  let text =
    source && source !== targetFormat
      ? convert(fullContents.text, source, targetFormat)
      : fullContents.text;
  const isSchema = concept.is_schema;
  let schema: Concept | undefined = undefined;
  if (!isSchema && concept.schema_id) {
    const schemaResponse = await supabase
      .from("Concept")
      .select()
      .eq("id", concept.schema_id)
      .maybeSingle();
    if (schemaResponse.error) {
      return createApiResponse(request, schemaResponse);
    }
    if (!schemaResponse.data) {
      return createApiResponse(
        request,
        asPostgrestFailure("Resource schema not found", "404", 404),
      );
    }
    schema = schemaResponse.data;
  }
  const schemaName = conceptName(concept, schema);

  if (includeData) {
    const authorId = concept.author_id ?? contents[0]?.author_id;
    let author: PlatformAccount | undefined = undefined;
    if (authorId) {
      try {
        const authorResponse = await supabase
          .from("PlatformAccount")
          .select()
          .eq("id", authorId)
          .maybeSingle();
        if (authorResponse.data) author = authorResponse.data;
      } catch (error) {
        // Anonymous readers may not see accounts; the page is served without them.
        console.error(error);
      }
    }

    const addresses = await loadConceptAddresses({
      supabase,
      origin,
      concepts: schema ? [concept, schema] : [concept],
    });
    if ("failure" in addresses)
      return createApiResponse(request, addresses.failure);
    const jsonLdData = asJsonLD({
      platform,
      concept,
      addresses,
      ownSpaceUrl,
      title,
      schema,
      content: undefined,
      author,
      targetFormat,
      wrap: true,
    });
    text = `<div id="content">\n<script type="application/ld+json">${JSON.stringify(jsonLdData)}</script>\n${text}\n</div>`;
  }
  const divideFM = fullContents.text.split("---\n");
  const firstTextFragment =
    divideFM.length > 2 && divideFM[0]!.trim().length == 0
      ? divideFM[2]!
      : fullContents.text;

  const wrap = `<html><head>
    ${title ? '<meta property="og:title" content="' + title.text + '" />' : ""}
  <meta property="og:type" content="${schemaName}" />
  <meta property="og:url" content="${request.url}" />
  <meta property="og:description" content="${firstTextFragment.substring(0, 80)}" />
  </head>
  <body>
  <main>
  ${text}
  </main>
  </body>
  </html>
`;

  return new NextResponse(wrap, {
    headers: { "Content-Type": targetMimetype },
  });
};

export const OPTIONS = defaultOptionsHandler;

