cat >> app/utils/conversion/sanitizeHtml.ts <<'EOF'

// JSON for an inline `<script type="application/ld+json">`: escaping `<` keeps
// a `</script>` inside any string value from closing the element.
export const jsonForScript = (data: unknown): string =>
  JSON.stringify(data).replace(/</g, "\\u003c");
EOF
cat >> test/unit/sanitizeHtml.test.ts <<'EOF'

describe("jsonForScript", () => {
  it("keeps a closing script tag inside the JSON", () => {
    const serialized = jsonForScript({ title: "</script><script>alert(1)" });
    expect(serialized).not.toContain("</script>");
    expect(JSON.parse(serialized)).toEqual({
      title: "</script><script>alert(1)",
    });
  });
});
EOF
sed -i '' 's/^  escapeHtml,$/  escapeHtml,\n  jsonForScript,/' test/unit/sanitizeHtml.test.ts && head -6 test/unit/sanitizeHtml.test.ts

