38:    "next": "^16.2.0",
  importPage(["blog", slug]);

const EXTERNAL_HREF_RE = /^https?:\/\//;

// Overrides Nextra's default MDX link component, which appends a
// non-breaking space and an arrow icon to every external link. Blog posts
// don't want that affordance, so render a plain anchor instead of hiding
// the icon with CSS (which would leave the orphaned space behind).
const BlogLink = ({
  href,
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement>): ReactElement => {
  const isExternal = typeof href === "string" && EXTERNAL_HREF_RE.test(href);

  return (
    <a
      href={href}
      target={isExternal ? "_blank" : undefined}
      rel={isExternal ? "noreferrer" : undefined}
      {...props}
    />
  );
};

const getMetadataDescription = ({
  description,
  metadata,
}: {
  description?: string;
  metadata: Metadata;
}): string | undefined =>
  description ??
  (typeof metadata.description === "string" ? metadata.description : undefined);

const buildBlogPostMetadata = ({
  blog,
  pageMetadata,
}: {
  blog: BlogData;
  pageMetadata: Metadata;
}): Metadata => {
            </span>
            <span className="rounded-full border border-slate-200 bg-slate-100 px-2 py-0.5 text-[11px] font-semibold uppercase tracking-[0.08em] text-slate-700">
              Extract
            </span>
          </Link>

          <Link
            href="/"
            className="rounded-full border border-transparent px-3 py-1.5 text-[14px] font-medium text-slate-500 no-underline transition-colors hover:border-slate-200 hover:bg-white hover:text-slate-700"
          >
            Back to site
          </Link>
        </div>
      </header>

      <main className="flex min-h-0 flex-1">{children}</main>
    </div>
  );
};

export default ExtractLayout;

