import { describe, it, expect } from "vitest";
import { convert, stripFrontmatter } from "../../app/utils/conversion/convert";

const NOTE = `---
nodeTypeId: node_G_B1s5HQk0MoI5JpI9Ui9
nodeInstanceId: 01a11c81
---
Some *body* text.`;

describe("stripFrontmatter", () => {
  it("removes a leading YAML block", () => {
    expect(stripFrontmatter(NOTE)).toBe("Some *body* text.");
  });

  it("removes a frontmatter-only note entirely", () => {
    expect(stripFrontmatter("---\na: 1\n---\n")).toBe("");
    expect(stripFrontmatter("---\na: 1\n---")).toBe("");
  });

  it("leaves text without leading frontmatter alone", () => {
    expect(stripFrontmatter("Intro\n---\na: 1\n---\n")).toBe(
      "Intro\n---\na: 1\n---\n",
    );
  });
});

describe("convert", () => {
  it("drops Obsidian frontmatter when rendering HTML", () => {
    expect(convert(NOTE, "obsidian", "html")).toBe(
      "<p>Some <em>body</em> text.</p>",
    );
  });

  it("keeps the stored text for markdown formats", () => {
    expect(convert(NOTE, "obsidian", "markdown")).toBe(NOTE);
  });
});

