p='app/utils/conversion/convert.ts'
s=open(p).read()
old=s[s.index('const FRONTMATTER_RE'):s.index('  if (markdownTypes.has(dest) && source === "html") {')]
new='''const FRONTMATTER_RE = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---(?:\\r?\\n|$)/;

// Obsidian notes start with YAML frontmatter: metadata, kept apart from the body.
export const splitFrontmatter = (
  text: string,
): { frontmatter?: string; body: string } => {
  const match = FRONTMATTER_RE.exec(text);
  if (!match) return { body: text };
  return { frontmatter: match[1], body: text.substring(match[0].length) };
};

// Shown collapsed above the body, under Obsidian's name for it.
const frontmatterHtml = (frontmatter: string): string =>
  `<details class="frontmatter"><summary>Properties</summary><pre><code class="language-yaml">${escapeHtml(frontmatter)}</code></pre></details>\\n`;

export const convert = (
  text: string,
  source: DocType,
  dest: DocType,
): string => {
  if (source === dest) return text;
  // punt details
  if (markdownTypes.has(source) && markdownTypes.has(dest)) return text;
  converter = init();
  if (markdownTypes.has(source) && dest === "html") {
    if (source !== "obsidian") return converter.makeHtml(text);
    const { frontmatter, body } = splitFrontmatter(text);
    return (
      (frontmatter ? frontmatterHtml(frontmatter) : "") +
      converter.makeHtml(body)
    );
  }
'''
s=s.replace(old,new)
s=s.replace('import { JSDOM } from "jsdom";\n','import { JSDOM } from "jsdom";\nimport { escapeHtml } from "~/utils/conversion/sanitizeHtml";\n')
open(p,'w').write(s)
EOF
cat > test/unit/convert.test.ts <<'EOF'
import { describe, it, expect } from "vitest";
import {
  convert,
  splitFrontmatter,
} from "../../app/utils/conversion/convert";
import { sanitizeHtml } from "../../app/utils/conversion/sanitizeHtml";

const NOTE = `---
nodeTypeId: node_G_B1s5HQk0MoI5JpI9Ui9
nodeInstanceId: 01a11c81
---
Some *body* text.`;

const PROPERTIES = `<details class="frontmatter"><summary>Properties</summary><pre><code class="language-yaml">nodeTypeId: node_G_B1s5HQk0MoI5JpI9Ui9
nodeInstanceId: 01a11c81</code></pre></details>
`;

describe("splitFrontmatter", () => {
  it("separates a leading YAML block from the body", () => {
    expect(splitFrontmatter(NOTE)).toEqual({
      frontmatter: "nodeTypeId: node_G_B1s5HQk0MoI5JpI9Ui9\nnodeInstanceId: 01a11c81",
      body: "Some *body* text.",
    });
  });

  it("handles a frontmatter-only note", () => {
    expect(splitFrontmatter("---\na: 1\n---\n")).toEqual({
      frontmatter: "a: 1",
      body: "",
    });
    expect(splitFrontmatter("---\na: 1\n---")).toEqual({
      frontmatter: "a: 1",
      body: "",
    });
  });

  it("leaves text without leading frontmatter alone", () => {
    expect(splitFrontmatter("Intro\n---\na: 1\n---\n")).toEqual({
      body: "Intro\n---\na: 1\n---\n",
    });
  });
});

describe("convert", () => {
  it("renders Obsidian frontmatter as a collapsed YAML block", () => {
    expect(convert(NOTE, "obsidian", "html")).toBe(
      `${PROPERTIES}<p>Some <em>body</em> text.</p>`,
    );
  });

  it("escapes markup inside the frontmatter", () => {
    const html = convert("---\nx: <script>\n---\n", "obsidian", "html");
    expect(html).toContain("x: &lt;script&gt;");
  });

  it("keeps the properties block through sanitizing", () => {
    expect(sanitizeHtml(PROPERTIES)).toBe(PROPERTIES);
  });

  it("keeps the stored text for markdown formats", () => {
    expect(convert(NOTE, "obsidian", "markdown")).toBe(NOTE);
  });
});
EOF
