                  <Checkbox
                    key={group.id}
                    checked={selectedGroupIds.includes(group.id)}
                    label={group.name}
                    onChange={(e) => {
                      const { checked } = e.target as HTMLInputElement;
                      setSelectedGroupIds((prev) =>
                        checked
                          ? [...prev, group.id]
                          : prev.filter((id) => id !== group.id),
                      );
                    }}
                  />
                ))}
              </>
